import{bV as r,aL as o,u as n,G as a}from"./chunks/framework.BidoRKjm.js";const u=JSON.parse('{"title":"简历","description":"","frontmatter":{"title":"简历","sidebar":false,"prev":false,"next":false,"comment":false,"articleUpdate":false},"headers":[],"relativePath":"resume.md","filePath":"about/resume/index.md","lastUpdated":1788192834000}'),s={name:"resume.md"};function e(l,t,i,g,h,d){return o(),n("div",null,[...t[0]||(t[0]=[a('<h1 id="简历" tabindex="-1">简历 <a class="header-anchor" href="#简历" aria-label="Permalink to &quot;简历&quot;">​</a></h1><h2 id="基本信息" tabindex="-1">基本信息 <a class="header-anchor" href="#基本信息" aria-label="Permalink to &quot;基本信息&quot;">​</a></h2><ul><li><strong>姓名</strong>：陌北</li><li><strong>年龄</strong>：20</li><li><strong>性别</strong>：男</li><li><strong>求职意向</strong>：全栈开发工程师</li></ul><h2 id="专业技能" tabindex="-1">专业技能 <a class="header-anchor" href="#专业技能" aria-label="Permalink to &quot;专业技能&quot;">​</a></h2><ul><li><strong>前端</strong>：熟练掌握 <strong>HTML / CSS / JS / TS</strong>，熟练使用 <strong>Vue / React</strong> 配合 <strong>Tailwind CSS / Element Plus</strong> 等组件库进行组件化开发</li><li><strong>多端开发</strong>：掌握 <strong>Uniapp / React Native</strong> 跨端开发，了解 <strong>Electron / PySider</strong> 桌面应用开发</li><li><strong>后端</strong>：熟练使用 <strong>Python / Java / Go</strong>，熟悉 <strong>FastAPI / Spring Boot</strong>、了解<strong>Gin</strong> 等框架，了解 <strong>Casbin/ Redis/ MQ</strong> 中间件</li><li><strong>数据库</strong>：熟练使用 <strong>MySQL / PostgreSQL</strong>，能够独立完成数据库设计与维护</li><li><strong>通信协议</strong>：掌握 <strong>WebSocket / HTTP / SSE</strong> 等通信协议</li><li><strong>测试与可视化</strong>：熟悉 <strong>Selenium / Playwright</strong> 自动化测试，掌握 <strong>ECharts</strong>，了解 <strong>D3.js</strong> 数据可视化</li><li><strong>运维</strong>：熟悉 <strong>Linux / Docker / 1Panel</strong>，了解 <strong>宝塔面板</strong>，熟练使用 <strong>Wireshark</strong> 抓包分析与 <strong>Tailscale</strong> 组网</li><li><strong>版本控制</strong>：熟练使用 <strong>Git</strong>，熟悉 <strong>GitHub Actions</strong> 流水线配置</li></ul><h2 id="实战经历" tabindex="-1">实战经历 <a class="header-anchor" href="#实战经历" aria-label="Permalink to &quot;实战经历&quot;">​</a></h2><h3 id="聊天室系统" tabindex="-1">聊天室系统 <a class="header-anchor" href="#聊天室系统" aria-label="Permalink to &quot;聊天室系统&quot;">​</a></h3><p><strong>2024.4 — 至今</strong> | 个人项目 | Python 全栈</p><ul><li>使用 Flask 构建实时聊天系统，支持多用户同时在线</li><li>采用 MySQL 数据库存储用户信息、房间信息、聊天记录等数据</li><li>通过 WebSocket 进行低延迟（&lt;100ms）的实时消息传递</li><li>通过 SSE 实现服务器向客户端推送消息，提升用户体验</li><li>采用 Redis 缓存用户会话，提升系统响应速度</li><li>实现 JWT 用户认证体系，保障系统安全性</li></ul><h3 id="数智体测平台" tabindex="-1">数智体测平台 <a class="header-anchor" href="#数智体测平台" aria-label="Permalink to &quot;数智体测平台&quot;">​</a></h3><p><strong>2026.2 — 2026.3</strong> | 双人协作 | Go 全栈</p><h4 id="背景" tabindex="-1">背景 <a class="header-anchor" href="#背景" aria-label="Permalink to &quot;背景&quot;">​</a></h4><p>为学校体测数据管理提供数字化方案，基于 Gin 构建数智体测平台，支持单点登录、体测记录管理、权限管理、Excel 导入导出、审计等功能，旨在提升体测数据管理效率</p><h4 id="所用技术" tabindex="-1">所用技术 <a class="header-anchor" href="#所用技术" aria-label="Permalink to &quot;所用技术&quot;">​</a></h4><p>Gin、PostgreSQL、Redis、Casbin、Excelize、CAS、JWT</p><h4 id="投入与成果" tabindex="-1">投入与成果 <a class="header-anchor" href="#投入与成果" aria-label="Permalink to &quot;投入与成果&quot;">​</a></h4><ul><li><strong>框架构建</strong>：基于 <strong>Gin</strong> 构建 RESTful API，支持用户单点登录、体测记录管理、权限管理、Excel 导入导出、审计等功能</li><li><strong>数据处理</strong>：采用 <strong>Excelize</strong> 库处理 Excel 文件，支持读写 Excel 文件，实现体测记录批量导入导出</li><li><strong>数据存储</strong>：采用 <strong>PostgreSQL</strong> 数据库存储用户信息、体测记录、权限信息、审计日志等数据</li><li><strong>会话缓存</strong>：采用 <strong>Redis</strong> 缓存用户会话，提升系统响应速度</li><li><strong>单点登录</strong>：集成学校 <strong>CAS</strong> 实现单点登录，同时保留本地账号密码登录作为兜底；统一签发 <strong>JWT</strong> 令牌进行会话管理，确保不同登录方式下的鉴权逻辑一致</li><li><strong>权限管理</strong>：使用 <strong>Casbin</strong> 实现 RBAC 权限管理，确保用户权限安全</li></ul><h3 id="个人私有云搭建与维护" tabindex="-1">个人私有云搭建与维护 <a class="header-anchor" href="#个人私有云搭建与维护" aria-label="Permalink to &quot;个人私有云搭建与维护&quot;">​</a></h3><p><strong>2026.6 — 至今</strong> | 个人项目 | 运维开发</p><h4 id="背景-1" tabindex="-1">背景 <a class="header-anchor" href="#背景-1" aria-label="Permalink to &quot;背景&quot;">​</a></h4><p>为构建统一的全栈开发环境与个人数据中心，利用闲置x86硬件资源，基于Linux和容器化技术搭建高可用私有云平台，旨在解决多环境依赖冲突及数据孤岛问题</p><h4 id="所用技术-1" tabindex="-1">所用技术 <a class="header-anchor" href="#所用技术-1" aria-label="Permalink to &quot;所用技术&quot;">​</a></h4><p>Python、Docker、Tailscale、Mise、1Panel、Crontab</p><h4 id="投入与成果-1" tabindex="-1">投入与成果 <a class="header-anchor" href="#投入与成果-1" aria-label="Permalink to &quot;投入与成果&quot;">​</a></h4><ul><li><strong>容器部署与编排</strong>：基于 <strong>Docker Compose</strong> 编排 20+ 容器（含数据库及可视化工具、网络磁盘映射器、密码库、流媒体、无头浏览器、监控等）按需启停，实现个人全栈开发环境集中管理</li><li><strong>多版本运行时环境构建</strong>：引入 <strong>Mise</strong> 统一管理 <strong>Java/Python/GO/Node</strong> 等多语言运行时、<strong>pnpm/uv</strong>包管理器，通过配置文件实现项目级环境隔离与自动激活，彻底解决本地开发环境的依赖冲突痛点</li><li><strong>可视化运维</strong>：部署 <strong>1Panel</strong> 现代化运维面板，集成系统监控与日志审计功能，将复杂的命令行操作图形化，提升日常巡检与故障排查效率</li><li><strong>异地组网</strong>：基于 <strong>Tailscale</strong> 组建异地虚拟局域网，确保服务在异地可访问，保障数据安全与传输隐私</li><li><strong>资源节省</strong>：利用 BIOS设置配合智能插座 实现服务器按需启动</li><li><strong>智能关机</strong>：独立开发 <strong>Python 守护进程</strong>，多维度采集 CPU/IO/网络负载指标；设计误关机策略结合 <strong>Crontab</strong> 定时轮询，实现无人值守时的自动休眠，实测降低长期运行功耗约 70%</li><li><strong>自动化</strong>：编写 <strong>Python 脚本</strong>，实现缓存自动清理、数据库/容器定期备份、日志自动轮转删除，将日常运维工作量降低约 80%</li></ul><h2 id="获奖经历" tabindex="-1">获奖经历 <a class="header-anchor" href="#获奖经历" aria-label="Permalink to &quot;获奖经历&quot;">​</a></h2><ul><li>🥇 <strong>江西省职业院校技能大赛</strong> — 金奖</li><li>🥈 <strong>一带一路暨金砖国家技能发展与技术创新大赛</strong> — 银奖</li><li>🥈 <strong>大学生创新创业大赛</strong> — 银奖</li></ul><h2 id="联系方式" tabindex="-1">联系方式 <a class="header-anchor" href="#联系方式" aria-label="Permalink to &quot;联系方式&quot;">​</a></h2><ul><li><strong>GitHub</strong>：<a href="https://github.com/mobei-front" target="_blank" rel="noreferrer">mobei-front</a></li><li><strong>邮箱</strong>：<a href="mailto:2811218461@qq.com" target="_blank" rel="noreferrer">2811218461@qq.com</a></li></ul>',29)])])}const b=r(s,[["render",e]]);export{u as __pageData,b as default};
